fun solve(n: Int, edges: List<Pair<Int, Int>>): Int {
    val maxDominoes = 0
    val used = mutableSetOf<Pair<Int, Int>>()
    val vertexValues = IntArray(n + 1) { -1 }
    val edgeAssignments = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until edges.size) {
        edgeAssignments.add(Pair(0, 0))
    }
    val max = dfs(edges, 0, used, vertexValues, edgeAssignments)
    return max
}

fun dfs(edges: List<Pair<Int, Int>>, index: Int, used: MutableSet<Pair<Int, Int>>, vertexValues: IntArray, edgeAssignments: MutableList<Pair<Int, Int>>): Int {
    if (index == edges.size) {
        return 0
    }
    val currentEdge = edges[index]
    var max = 0
    for (a in 1..6) {
        for (b in a..6) {
            if (used.contains(Pair(a, b))) {
                continue
            }
            val valid = checkAndAssign(currentEdge, a, b, vertexValues, edgeAssignments, index)
            if (valid) {
                used.add(Pair(a, b))
                edgeAssignments[index] = Pair(a, b)
                val res = 1 + dfs(edges, index + 1, used, vertexValues, edgeAssignments)
                if (res > max) {
                    max = res
                }
                used.remove(Pair(a, b))
                edgeAssignments[index] = Pair(0, 0)
                revertAssignment(currentEdge, a, b, vertexValues)
            }
            if (a != b) {
                val validReversed = checkAndAssign(currentEdge, b, a, vertexValues, edgeAssignments, index)
                if (validReversed) {
                    used.add(Pair(a, b))
                    edgeAssignments[index] = Pair(b, a)
                    val res = 1 + dfs(edges, index + 1, used, vertexValues, edgeAssignments)
                    if (res > max) {
                        max = res
                    }
                    used.remove(Pair(a, b))
                    edgeAssignments[index] = Pair(0, 0)
                    revertAssignment(currentEdge, b, a, vertexValues)
                }
            }
        }
    }
    val skip = dfs(edges, index + 1, used, vertexValues, edgeAssignments)
    if (skip > max) {
        max = skip
    }
    return max
}

fun checkAndAssign(edge: Pair<Int, Int>, a: Int, b: Int, vertexValues: IntArray, edgeAssignments: MutableList<Pair<Int, Int>>, index: Int): Boolean {
    val u = edge.first
    val v = edge.second
    if (vertexValues[u] != -1 && vertexValues[u] != a) {
        return false
    }
    if (vertexValues[v] != -1 && vertexValues[v] != b) {
        return false
    }
    val prevU = vertexValues[u]
    val prevV = vertexValues[v]
    vertexValues[u] = a
    vertexValues[v] = b
    edgeAssignments[index] = Pair(a, b)
    return true
}

fun revertAssignment(edge: Pair<Int, Int>, a: Int, b: Int, vertexValues: IntArray) {
    val u = edge.first
    val v = edge.second
    vertexValues[u] = -1
    vertexValues[v] = -1
}
