fun backtrack(pos: Int, count: Int, edges: List<Pair<Int, Int>>, used: Array<IntArray>, vertexValues: IntArray, dominoes: List<Pair<Int, Int>>, max: Int, result: Int) {
    if (count > result) {
        result = count
    }
    if (pos >= edges.size || count + (edges.size - pos) <= result) {
        return
    }
    val (u, v) = edges[pos]
    // Try not using this edge
    backtrack(pos + 1, count, edges, used, vertexValues, dominoes, max, result)
    // Try using this edge with all possible dominoes and orientations
    for (domino in dominoes) {
        val (a, b) = domino
        if (used[a][b] == 1) continue
        // Try a -> u, b -> v
        if (canPlace(u, v, a, b, vertexValues)) {
            used[a][b] = 1
            val prevU = vertexValues[u]
            val prevV = vertexValues[v]
            vertexValues[u] = a
            vertexValues[v] = b
            backtrack(pos + 1, count + 1, edges, used, vertexValues, dominoes, max, result)
            vertexValues[u] = prevU
            vertexValues[v] = prevV
            used[a][b] = 0
        }
        // Try b -> u, a -> v
        if (a != b && canPlace(u, v, b, a, vertexValues)) {
            used[a][b] = 1
            val prevU = vertexValues[u]
            val prevV = vertexValues[v]
            vertexValues[u] = b
            vertexValues[v] = a
            backtrack(pos + 1, count + 1, edges, used, vertexValues, dominoes, max, result)
            vertexValues[u] = prevU
            vertexValues[v] = prevV
            used[a][b] = 0
        }
    }
}

fun canPlace(u: Int, v: Int, a: Int, b: Int, vertexValues: IntArray): Boolean {
