import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val edges = mutableListOf<Pair<Int, Int>>()
    repeat(m) {
        val (a, b) = br.readLine().split(" ").map { it.toInt() }
        edges.add(Pair(a - 1, b - 1))
    }

    var max = 0

    // Iterate over all possible assignments of numbers to vertices (1-6)
    for (assignment in generateAssignments(n)) {
        val used = mutableSetOf<Pair<Int, Int>>()
        var count = 0
        for ((u, v) in edges) {
            val a = assignment[u]
            val b = assignment[v]
            val domino = if (a <= b) Pair(a, b) else Pair(b, a)
            if (!used.contains(domino)) {
                used.add(domino)
                count++
            }
        }
        if (count > max) {
            max = count
        }
    }

    println(max)
}

fun generateAssignments(n: Int): List<List<Int>> {
    val assignments = mutableListOf<List<Int>>()
    val current = IntArray(n)
    generateAssignmentsHelper(0, n, current, assignments)
    return assignments
}

fun generateAssignmentsHelper(index: Int, n: Int, current: IntArray, assignments: MutableList<List<Int>>) {
    if (index == n) {
        assignments.add(current.toList())
        return
    }
    for (i in 1..6) {
        current[index] = i
        generateAssignmentsHelper(index + 1, n, current, assignments)
    }
}
