import java.util.*

fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextInt()
    val m = sc.nextInt()
    val edges = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until m) {
        val a = sc.nextInt()
        val b = sc.nextInt()
        edges.add(Pair(a, b))
    }
    val maxDominoes = solve(n, edges)
    println(maxDominoes)
}

fun solve(n: Int, edges: List<Pair<Int, Int>>): Int {
    val max = 21
    val used = BooleanArray(max + 1)
    val vertexValues = IntArray(n + 1) { -1 }
    var result = 0
    val edgeList = edges.mapIndexed { index, pair -> Edge(index, pair.first, pair.second) }
    val sortedEdges = edgeList.sortedBy { it.index }
    return backtrack(sortedEdges, 0, used, vertexValues, 0)
}

data class Edge(val index: Int, val u: Int, val v: Int)

fun backtrack(edges: List<Edge>, pos: Int, used: BooleanArray, vertexValues: IntArray, count: Int): Int {
    if (pos >= edges.size) {
        return count
    }
    var max = count
    val edge = edges[pos]
    for (a in 1..6) {
        for (b in a..6) {
            val dominoId = (a - 1) * 6 + a + (b - a)
            if (dominoId > 21) continue
            if (used[dominoId]) continue
            val valid = checkEdge(edge, a, b, vertexValues)
            if (valid.first) {
                used[dominoId] = true
                val savedU = vertexValues[edge.u]
                val savedV = vertexValues[edge.v]
                vertexValues[edge.u] = valid.second
                vertexValues[edge.v] = valid.third
                val res = backtrack(edges, pos + 1, used, vertexValues, count + 1)
                if (res > max) max = res
                used[dominoId] = false
                vertexValues[edge.u] = savedU
                vertexValues[edge.v] = savedV
            }
            if (a != b) {
                val validRev = checkEdge(edge, b, a, vertexValues)
                if (validRev.first) {
                    used[dominoId] = true
                    val savedU = vertexValues[edge.u]
                    val savedV = vertexValues[edge.v]
                    vertexValues[edge.u] = validRev.second
                    vertexValues[edge.v] = validRev.third
                    val res = backtrack(edges, pos + 1, used, vertexValues, count + 1)
                    if (res > max) max = res
                    used[dominoId] = false
                    vertexValues[edge.u] = savedU
                    vertexValues[edge.v] = savedV
                }
            }
        }
    }
    val skip = backtrack(edges, pos + 1, used, vertexValues, count)
    if (skip > max) max = skip
    return max
}

fun checkEdge(edge: Edge, a: Int, b: Int, vertexValues: IntArray): Triple<Boolean, Int, Int> {
    val uVal = vertexValues[edge.u]
    val vVal = vertexValues[edge.v]
    if (uVal != -1 && uVal != a) return Triple(false, 0, 0)
    if (vVal != -1 && vVal != b) return Triple(false, 0, 0)
    return Triple(true, a, b)
}
