import java.util.*

fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextInt()
    val m = sc.nextInt()
    val edges = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until m) {
        val a = sc.nextInt()
        val b = sc.nextInt()
        edges.add(Pair(a, b))
    }
    val maxDominoes = solve(n, edges)
    println(maxMaxDominoes(maxDominoes))
}

fun solve(n: Int, edges: List<Pair<Int, Int>>): Int {
    val adj = Array(n + 1) { mutableListOf<Int>() }
    for ((a, b) in edges) {
        adj[a].add(b)
        adj[b].add(a)
    }
    var max = 0
    val visited = BooleanArray(n + 1)
    val components = mutableListOf<List<Int>>()
    for (v in 1..n) {
        if (!visited[v]) {
            val comp = mutableListOf<Int>()
            dfs(v, adj, visited, comp)
            components.add(comp)
        }
    }
    for (comp in components) {
        val compEdges = edges.filter { (a, b) -> comp.contains(a) && comp.contains(b) }
        val compAdj = Array(comp.size) { mutableListOf<Int>() }
        val indexMap = comp.withIndex().associate { it.value to it.index }
        for ((a, b) in compEdges) {
            compAdj[indexMap[a]!!].add(indexMap[b]!!)
            compAdj[indexMap[b]!!].add(indexMap[a]!!)
        }
        val componentMax = maxMatching(compAdj)
        max += componentMax
    }
    return max
}

fun dfs(v: Int, adj: Array<MutableList<Int>>, visited: BooleanArray, comp: MutableList<Int>) {
    visited[v] = true
    comp.add(v)
    for (u in adj[v]) {
        if (!visited[u]) {
            dfs(u, adj, visited, comp)
        }
    }
}

fun maxMatching(adj: Array<MutableList<Int>>): Int {
    val n = adj.size
    val match = IntArray(n) { -1 }
    var result = 0
    for (u in 0 until n) {
        val visited = BooleanArray(n)
        if (dfs(u, adj, match, visited)) {
            result++
        }
    }
    return result
}

fun dfs(u: Int, adj: Array<MutableList<Int>>, match: IntArray, visited: BooleanArray): Boolean {
    for (v in adj[u]) {
        if (!visited[v]) {
            visited[v] = true
            if (match[v] == -1 || dfs(match[v], adj, match, visited)) {
                match[v] = u
                match[u] = v
                return true
            }
        }
    }
    return false
}

fun maxMaxDominoes(max: Int): Int {
    return max.coerceAtMost(21)
}
